-- IDPS | Zawiya Refinery | MySQL 8.4 LTS reference schema v1.1
-- DESIGN REFERENCE ONLY. Do not run against production; implement via Laravel migrations.
-- UUID IDs are CHAR(36) ascii_bin generated by Laravel (HasUuids).
-- Every DATETIME(6) timestamp is UTC; business_date is in Africa/Tripoli.
-- Requirements: InnoDB, STRICT_TRANS_TABLES, utf8mb4, MySQL 8.4 LTS.
-- App must check nullable composite keys and optimistic locking in transactions.
SET NAMES utf8mb4;
SET time_zone = '+00:00';

CREATE TABLE facilities (
  id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin PRIMARY KEY,
  code VARCHAR(64) UNIQUE NOT NULL,
  name_ar VARCHAR(255) NOT NULL,
  timezone_name VARCHAR(64) NOT NULL DEFAULT 'Africa/Tripoli',
  active BOOLEAN NOT NULL DEFAULT 1,
  created_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE refinery_units (
  id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin PRIMARY KEY,
  facility_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  parent_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin,
  code VARCHAR(64) NOT NULL,
  name_ar VARCHAR(255) NOT NULL,
  process_type TEXT NOT NULL,
  active BOOLEAN NOT NULL DEFAULT 1,
  UNIQUE (facility_id, code),
  CONSTRAINT fk_refinery_units_facility_id FOREIGN KEY (facility_id) REFERENCES facilities(id),
  CONSTRAINT fk_refinery_units_parent_id FOREIGN KEY (parent_id) REFERENCES refinery_units(id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE product_catalog (
  id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin PRIMARY KEY,
  code VARCHAR(64) UNIQUE NOT NULL,
  name_ar VARCHAR(255) NOT NULL,
  stage VARCHAR(40) NOT NULL CHECK (stage IN ('intermediate_stream','final_product','blend_additive','fuel','byproduct','waste','other')),
  active BOOLEAN NOT NULL DEFAULT 1
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE crude_catalog (
  id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin PRIMARY KEY,
  code VARCHAR(64) UNIQUE NOT NULL,
  name_ar VARCHAR(255) NOT NULL,
  active BOOLEAN NOT NULL DEFAULT 1
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE measurement_units (
  code VARCHAR(64) PRIMARY KEY,
  dimension VARCHAR(24) NOT NULL,
  display_symbol VARCHAR(24) NOT NULL,
  scale_note TEXT
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE users (
  id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin PRIMARY KEY,
  display_name VARCHAR(191) NOT NULL,
  email VARCHAR(191) UNIQUE NOT NULL,
  password_hash TEXT NOT NULL,
  active BOOLEAN NOT NULL DEFAULT 1,
  created_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE roles (
  id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin PRIMARY KEY,
  code VARCHAR(64) UNIQUE NOT NULL,
  name_ar VARCHAR(255) NOT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE permissions (
  id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin PRIMARY KEY,
  code VARCHAR(64) UNIQUE NOT NULL,
  description TEXT
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE user_roles (
  id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin PRIMARY KEY,
  user_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  role_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  facility_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin,
  unit_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin,
  facility_scope_key VARCHAR(36) CHARACTER SET ascii COLLATE ascii_bin GENERATED ALWAYS AS (COALESCE(facility_id,'GLOBAL')) STORED,
  unit_scope_key VARCHAR(36) CHARACTER SET ascii COLLATE ascii_bin GENERATED ALWAYS AS (COALESCE(unit_id,'GLOBAL')) STORED,
  UNIQUE KEY uq_user_role_scope (user_id,role_id,facility_scope_key,unit_scope_key),
  CONSTRAINT fk_user_roles_user_id FOREIGN KEY (user_id) REFERENCES users(id),
  CONSTRAINT fk_user_roles_role_id FOREIGN KEY (role_id) REFERENCES roles(id),
  CONSTRAINT fk_user_roles_facility_id FOREIGN KEY (facility_id) REFERENCES facilities(id),
  CONSTRAINT fk_user_roles_unit_id FOREIGN KEY (unit_id) REFERENCES refinery_units(id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE role_permissions (
  role_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  permission_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  PRIMARY KEY(role_id,permission_id),
  CONSTRAINT fk_role_permissions_role_id FOREIGN KEY (role_id) REFERENCES roles(id),
  CONSTRAINT fk_role_permissions_permission_id FOREIGN KEY (permission_id) REFERENCES permissions(id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE source_files (
  id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin PRIMARY KEY,
  original_name VARCHAR(255) NOT NULL,
  sha256 char(64) NOT NULL,
  storage_key VARCHAR(255) NOT NULL,
  media_type TEXT,
  granularity VARCHAR(20) NOT NULL CHECK(granularity IN ('daily','shift','monthly','annual','unknown')),
  uploaded_by CHAR(36) CHARACTER SET ascii COLLATE ascii_bin,
  uploaded_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  classification VARCHAR(32) NOT NULL DEFAULT 'internal',
  UNIQUE(sha256),
  CONSTRAINT fk_source_files_uploaded_by FOREIGN KEY (uploaded_by) REFERENCES users(id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE import_batches (
  id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin PRIMARY KEY,
  source_file_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  parser_version VARCHAR(64) NOT NULL,
  mapping_version VARCHAR(64) NOT NULL,
  status VARCHAR(32) NOT NULL CHECK(status IN ('uploaded','parsed','mapped','validated','awaiting_review','approved','rejected','failed')),
  submitted_by CHAR(36) CHARACTER SET ascii COLLATE ascii_bin,
  approved_by CHAR(36) CHARACTER SET ascii COLLATE ascii_bin,
  created_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  approved_at DATETIME(6),
  error_count int NOT NULL DEFAULT 0 CHECK(error_count >= 0),
  CONSTRAINT fk_import_batches_source_file_id FOREIGN KEY (source_file_id) REFERENCES source_files(id),
  CONSTRAINT fk_import_batches_submitted_by FOREIGN KEY (submitted_by) REFERENCES users(id),
  CONSTRAINT fk_import_batches_approved_by FOREIGN KEY (approved_by) REFERENCES users(id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE import_rows (
  id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin PRIMARY KEY,
  batch_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  sheet_name VARCHAR(128),
  row_number int,
  source_metric VARCHAR(64) NOT NULL,
  source_cell VARCHAR(32),
  raw_value TEXT,
  normalized_value DECIMAL(20,6),
  normalized_unit TEXT,
  mapping_status VARCHAR(32) NOT NULL DEFAULT 'unreviewed',
  validation_messages JSON NOT NULL DEFAULT (JSON_ARRAY()),
  UNIQUE(batch_id,sheet_name,row_number,source_metric),
  CONSTRAINT fk_import_rows_batch_id FOREIGN KEY (batch_id) REFERENCES import_batches(id),
  CONSTRAINT fk_import_rows_normalized_unit FOREIGN KEY (normalized_unit) REFERENCES measurement_units(code)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE approval_actions (
  id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin PRIMARY KEY,
  resource_type VARCHAR(64) NOT NULL,
  resource_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  action VARCHAR(32) NOT NULL CHECK(action IN ('submit','approve','reject','supersede','cancel')),
  actor_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin,
  reason TEXT,
  at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  CONSTRAINT fk_approval_actions_actor_id FOREIGN KEY (actor_id) REFERENCES users(id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE audit_logs (
  id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin PRIMARY KEY,
  request_id VARCHAR(128),
  actor_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin,
  resource_type VARCHAR(64) NOT NULL,
  resource_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin,
  action VARCHAR(32) NOT NULL,
  before_value JSON,
  after_value JSON,
  reason TEXT,
  happened_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  CONSTRAINT fk_audit_logs_actor_id FOREIGN KEY (actor_id) REFERENCES users(id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE production_target_plans (
  id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin PRIMARY KEY,
  facility_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  title VARCHAR(255) NOT NULL,
  version_no int NOT NULL CHECK(version_no > 0),
  valid_from date NOT NULL,
  valid_to date NOT NULL,
  status VARCHAR(32) NOT NULL DEFAULT 'draft'
 CHECK(status IN ('draft','submitted','approved','rejected','superseded')),
  created_by CHAR(36) CHARACTER SET ascii COLLATE ascii_bin,
  approved_by CHAR(36) CHARACTER SET ascii COLLATE ascii_bin,
  known_at DATETIME(6),
  created_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  CHECK(valid_to >= valid_from),
  UNIQUE(facility_id,version_no),
  CONSTRAINT fk_production_target_plans_facility_id FOREIGN KEY (facility_id) REFERENCES facilities(id),
  CONSTRAINT fk_production_target_plans_created_by FOREIGN KEY (created_by) REFERENCES users(id),
  CONSTRAINT fk_production_target_plans_approved_by FOREIGN KEY (approved_by) REFERENCES users(id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE production_targets (
  id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin PRIMARY KEY,
  plan_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  unit_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin,
  product_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  period_start date NOT NULL,
  period_end date NOT NULL,
  target_t DECIMAL(20,3) NOT NULL CHECK(target_t>=0),
  CHECK(period_end >= period_start),
  unit_scope_key VARCHAR(36) CHARACTER SET ascii COLLATE ascii_bin GENERATED ALWAYS AS (COALESCE(unit_id,'GLOBAL')) STORED,
  UNIQUE KEY uq_target_scope (plan_id,product_id,unit_scope_key,period_start,period_end),
  CONSTRAINT fk_production_targets_plan_id FOREIGN KEY (plan_id) REFERENCES production_target_plans(id),
  CONSTRAINT fk_production_targets_unit_id FOREIGN KEY (unit_id) REFERENCES refinery_units(id),
  CONSTRAINT fk_production_targets_product_id FOREIGN KEY (product_id) REFERENCES product_catalog(id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE planned_shutdowns (
  id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin PRIMARY KEY,
  unit_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  plan_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin,
  planned_start DATETIME(6) NOT NULL,
  planned_end DATETIME(6) NOT NULL,
  known_at DATETIME(6) NOT NULL,
  status VARCHAR(32) NOT NULL CHECK(status IN ('draft','submitted','approved','cancelled','superseded')),
  reason TEXT,
  revision_no int NOT NULL DEFAULT 1,
  CHECK(planned_end>planned_start),
  CONSTRAINT fk_planned_shutdowns_unit_id FOREIGN KEY (unit_id) REFERENCES refinery_units(id),
  CONSTRAINT fk_planned_shutdowns_plan_id FOREIGN KEY (plan_id) REFERENCES production_target_plans(id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE crude_feed_records (
  id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin PRIMARY KEY,
  unit_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  crude_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  business_date date NOT NULL,
  shift_code VARCHAR(30),
  quantity_t DECIMAL(20,3) NOT NULL CHECK(quantity_t>=0),
  observed_at DATETIME(6),
  available_at DATETIME(6) NOT NULL,
  source_file_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin,
  source_reference VARCHAR(255),
  status VARCHAR(32) NOT NULL DEFAULT 'draft' CHECK(status IN ('draft','submitted','approved','rejected','superseded')),
  revision_no int NOT NULL DEFAULT 1,
  replaces_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin,
  created_by CHAR(36) CHARACTER SET ascii COLLATE ascii_bin,
  approved_by CHAR(36) CHARACTER SET ascii COLLATE ascii_bin,
  created_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  CONSTRAINT fk_crude_feed_records_unit_id FOREIGN KEY (unit_id) REFERENCES refinery_units(id),
  CONSTRAINT fk_crude_feed_records_crude_id FOREIGN KEY (crude_id) REFERENCES crude_catalog(id),
  CONSTRAINT fk_crude_feed_records_source_file_id FOREIGN KEY (source_file_id) REFERENCES source_files(id),
  CONSTRAINT fk_crude_feed_records_replaces_id FOREIGN KEY (replaces_id) REFERENCES crude_feed_records(id),
  CONSTRAINT fk_crude_feed_records_created_by FOREIGN KEY (created_by) REFERENCES users(id),
  CONSTRAINT fk_crude_feed_records_approved_by FOREIGN KEY (approved_by) REFERENCES users(id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE production_records (
  id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin PRIMARY KEY,
  unit_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  product_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  business_date date NOT NULL,
  shift_code VARCHAR(30),
  quantity_t DECIMAL(20,3) NOT NULL CHECK(quantity_t>=0),
  measurement_stage VARCHAR(40) NOT NULL,
  observed_at DATETIME(6),
  available_at DATETIME(6) NOT NULL,
  source_file_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin,
  source_reference VARCHAR(255),
  status VARCHAR(32) NOT NULL DEFAULT 'draft' CHECK(status IN ('draft','submitted','approved','rejected','superseded')),
  revision_no int NOT NULL DEFAULT 1,
  replaces_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin,
  created_by CHAR(36) CHARACTER SET ascii COLLATE ascii_bin,
  approved_by CHAR(36) CHARACTER SET ascii COLLATE ascii_bin,
  created_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  CONSTRAINT fk_production_records_unit_id FOREIGN KEY (unit_id) REFERENCES refinery_units(id),
  CONSTRAINT fk_production_records_product_id FOREIGN KEY (product_id) REFERENCES product_catalog(id),
  CONSTRAINT fk_production_records_source_file_id FOREIGN KEY (source_file_id) REFERENCES source_files(id),
  CONSTRAINT fk_production_records_replaces_id FOREIGN KEY (replaces_id) REFERENCES production_records(id),
  CONSTRAINT fk_production_records_created_by FOREIGN KEY (created_by) REFERENCES users(id),
  CONSTRAINT fk_production_records_approved_by FOREIGN KEY (approved_by) REFERENCES users(id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE monthly_observations (
  id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin PRIMARY KEY,
  source_file_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  import_row_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin,
  facility_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin,
  metric_code VARCHAR(64) NOT NULL,
  item_code VARCHAR(64) NOT NULL,
  actual_or_target VARCHAR(16) NOT NULL
 CHECK(actual_or_target IN ('actual','target')),
  period_month date NOT NULL,
  quantity DECIMAL(20,6),
  unit_code VARCHAR(16),
  status VARCHAR(32) NOT NULL DEFAULT 'awaiting_review',
  revision_no int NOT NULL DEFAULT 1,
  import_row_scope_key VARCHAR(36) CHARACTER SET ascii COLLATE ascii_bin GENERATED ALWAYS AS (COALESCE(import_row_id,'GLOBAL')) STORED,
  CONSTRAINT fk_monthly_observations_source_file_id FOREIGN KEY (source_file_id) REFERENCES source_files(id),
  CONSTRAINT fk_monthly_observations_import_row_id FOREIGN KEY (import_row_id) REFERENCES import_rows(id),
  CONSTRAINT fk_monthly_observations_facility_id FOREIGN KEY (facility_id) REFERENCES facilities(id),
  CONSTRAINT fk_monthly_observations_unit_code FOREIGN KEY (unit_code) REFERENCES measurement_units(code)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE unit_status_intervals (
  id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin PRIMARY KEY,
  unit_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  state VARCHAR(30) NOT NULL CHECK(state IN ('running','standby','startup','shutdown','maintenance','trip','derated')),
  starts_at DATETIME(6) NOT NULL,
  ends_at DATETIME(6),
  entered_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  available_at DATETIME(6) NOT NULL,
  notes TEXT,
  source VARCHAR(64),
  CHECK(ends_at IS NULL OR ends_at > starts_at),
  CONSTRAINT fk_unit_status_intervals_unit_id FOREIGN KEY (unit_id) REFERENCES refinery_units(id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE operational_events (
  id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin PRIMARY KEY,
  unit_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  kind VARCHAR(24) NOT NULL CHECK(kind IN ('planned','unplanned')),
  event_type VARCHAR(64) NOT NULL,
  started_at DATETIME(6) NOT NULL,
  detected_at DATETIME(6),
  reported_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  known_at DATETIME(6) NOT NULL,
  expected_end_at DATETIME(6),
  actual_end_at DATETIME(6),
  reason_code VARCHAR(64),
  severity VARCHAR(20),
  source VARCHAR(64) NOT NULL,
  external_event_key VARCHAR(128),
  idempotency_key VARCHAR(128) NOT NULL UNIQUE,
  status VARCHAR(32) NOT NULL DEFAULT 'reported' CHECK(status IN ('reported','acknowledged','investigating','resolved','closed','cancelled')),
  revision_no int NOT NULL DEFAULT 1,
  notes TEXT,
  created_by CHAR(36) CHARACTER SET ascii COLLATE ascii_bin,
  approved_by CHAR(36) CHARACTER SET ascii COLLATE ascii_bin,
  CHECK(expected_end_at IS NULL OR expected_end_at > started_at),
  CHECK(actual_end_at IS NULL OR actual_end_at > started_at),
  CONSTRAINT fk_operational_events_unit_id FOREIGN KEY (unit_id) REFERENCES refinery_units(id),
  CONSTRAINT fk_operational_events_created_by FOREIGN KEY (created_by) REFERENCES users(id),
  CONSTRAINT fk_operational_events_approved_by FOREIGN KEY (approved_by) REFERENCES users(id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE event_revisions (
  id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin PRIMARY KEY,
  event_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  revision_no int NOT NULL,
  changed_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  changed_by CHAR(36) CHARACTER SET ascii COLLATE ascii_bin,
  reason TEXT,
  before_state JSON,
  after_state JSON,
  UNIQUE(event_id,revision_no),
  CONSTRAINT fk_event_revisions_event_id FOREIGN KEY (event_id) REFERENCES operational_events(id),
  CONSTRAINT fk_event_revisions_changed_by FOREIGN KEY (changed_by) REFERENCES users(id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE downtime_intervals (
  id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin PRIMARY KEY,
  event_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  unit_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  started_at DATETIME(6) NOT NULL,
  actual_end_at DATETIME(6),
  expected_end_at DATETIME(6),
  impact_fraction DECIMAL(6,4) NOT NULL DEFAULT 1 CHECK(impact_fraction >= 0 AND impact_fraction <= 1),
  status VARCHAR(32) NOT NULL DEFAULT 'active' CHECK(status IN ('active','restart_recorded','verified','finalized')),
  CHECK(actual_end_at IS NULL OR actual_end_at > started_at),
  CONSTRAINT fk_downtime_intervals_event_id FOREIGN KEY (event_id) REFERENCES operational_events(id),
  CONSTRAINT fk_downtime_intervals_unit_id FOREIGN KEY (unit_id) REFERENCES refinery_units(id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE energy_consumptions (
  id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin PRIMARY KEY,
  unit_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  business_date date NOT NULL,
  carrier_code VARCHAR(64) NOT NULL,
  measured_quantity DECIMAL(20,6) NOT NULL CHECK(measured_quantity>=0),
  measurement_unit VARCHAR(16) NOT NULL,
  known_at DATETIME(6) NOT NULL,
  status VARCHAR(32) NOT NULL DEFAULT 'draft',
  source_file_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin,
  created_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  CONSTRAINT fk_energy_consumptions_unit_id FOREIGN KEY (unit_id) REFERENCES refinery_units(id),
  CONSTRAINT fk_energy_consumptions_measurement_unit FOREIGN KEY (measurement_unit) REFERENCES measurement_units(code),
  CONSTRAINT fk_energy_consumptions_source_file_id FOREIGN KEY (source_file_id) REFERENCES source_files(id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE loss_records (
  id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin PRIMARY KEY,
  unit_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  business_date date NOT NULL,
  loss_category VARCHAR(64) NOT NULL,
  quantity_t DECIMAL(20,3) NOT NULL CHECK(quantity_t>=0),
  known_at DATETIME(6) NOT NULL,
  status VARCHAR(32) NOT NULL DEFAULT 'draft',
  source_file_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin,
  CONSTRAINT fk_loss_records_unit_id FOREIGN KEY (unit_id) REFERENCES refinery_units(id),
  CONSTRAINT fk_loss_records_source_file_id FOREIGN KEY (source_file_id) REFERENCES source_files(id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE chemicals (
  id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin PRIMARY KEY,
  code VARCHAR(64) UNIQUE NOT NULL,
  name_ar VARCHAR(255) NOT NULL,
  default_unit TEXT,
  CONSTRAINT fk_chemicals_default_unit FOREIGN KEY (default_unit) REFERENCES measurement_units(code)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE chemical_consumptions (
  id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin PRIMARY KEY,
  unit_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  chemical_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  business_date date NOT NULL,
  quantity DECIMAL(20,6) NOT NULL CHECK(quantity>=0),
  measurement_unit VARCHAR(16) NOT NULL,
  known_at DATETIME(6) NOT NULL,
  status VARCHAR(32) NOT NULL DEFAULT 'draft',
  source_file_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin,
  CONSTRAINT fk_chemical_consumptions_unit_id FOREIGN KEY (unit_id) REFERENCES refinery_units(id),
  CONSTRAINT fk_chemical_consumptions_chemical_id FOREIGN KEY (chemical_id) REFERENCES chemicals(id),
  CONSTRAINT fk_chemical_consumptions_measurement_unit FOREIGN KEY (measurement_unit) REFERENCES measurement_units(code),
  CONSTRAINT fk_chemical_consumptions_source_file_id FOREIGN KEY (source_file_id) REFERENCES source_files(id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE reconciliation_cases (
  id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin PRIMARY KEY,
  facility_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin,
  scope_key VARCHAR(128) NOT NULL,
  period_start date NOT NULL,
  period_end date NOT NULL,
  source_file_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin,
  expected_value DECIMAL(20,6),
  observed_value DECIMAL(20,6),
  difference DECIMAL(20,6),
  unit_code VARCHAR(16),
  status VARCHAR(32) NOT NULL DEFAULT 'open' CHECK(status IN ('open','in_review','accepted_source','resolved','waived')),
  explanation TEXT,
  resolved_by CHAR(36) CHARACTER SET ascii COLLATE ascii_bin,
  created_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  CONSTRAINT fk_reconciliation_cases_facility_id FOREIGN KEY (facility_id) REFERENCES facilities(id),
  CONSTRAINT fk_reconciliation_cases_source_file_id FOREIGN KEY (source_file_id) REFERENCES source_files(id),
  CONSTRAINT fk_reconciliation_cases_unit_code FOREIGN KEY (unit_code) REFERENCES measurement_units(code),
  CONSTRAINT fk_reconciliation_cases_resolved_by FOREIGN KEY (resolved_by) REFERENCES users(id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE kpi_definitions (
  id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin PRIMARY KEY,
  code VARCHAR(64) NOT NULL,
  version_no int NOT NULL DEFAULT 1,
  scope_definition JSON NOT NULL,
  formula_text TEXT NOT NULL,
  approved_by CHAR(36) CHARACTER SET ascii COLLATE ascii_bin,
  approved_at DATETIME(6),
  UNIQUE(code,version_no),
  CONSTRAINT fk_kpi_definitions_approved_by FOREIGN KEY (approved_by) REFERENCES users(id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE kpi_results (
  id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin PRIMARY KEY,
  definition_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  facility_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  unit_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin,
  product_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin,
  period_start date NOT NULL,
  period_end date NOT NULL,
  numerator DECIMAL(20,8),
  denominator DECIMAL(20,8),
  result_value DECIMAL(20,8),
  result_unit TEXT,
  result_status VARCHAR(40) NOT NULL,
  source_snapshot_sha256 char(64),
  calculated_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  CONSTRAINT fk_kpi_results_definition_id FOREIGN KEY (definition_id) REFERENCES kpi_definitions(id),
  CONSTRAINT fk_kpi_results_facility_id FOREIGN KEY (facility_id) REFERENCES facilities(id),
  CONSTRAINT fk_kpi_results_unit_id FOREIGN KEY (unit_id) REFERENCES refinery_units(id),
  CONSTRAINT fk_kpi_results_product_id FOREIGN KEY (product_id) REFERENCES product_catalog(id),
  CONSTRAINT fk_kpi_results_result_unit FOREIGN KEY (result_unit) REFERENCES measurement_units(code)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE dataset_snapshots (
  id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin PRIMARY KEY,
  product_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin,
  granularity VARCHAR(20) NOT NULL CHECK(granularity IN ('daily','shift','monthly')),
  period_start date NOT NULL,
  period_end date NOT NULL,
  row_count INT NOT NULL CHECK(row_count>=0),
  sha256 char(64) NOT NULL UNIQUE,
  feature_schema_version VARCHAR(64) NOT NULL,
  quality_report JSON NOT NULL DEFAULT (JSON_OBJECT()),
  approved_at DATETIME(6),
  created_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  CONSTRAINT fk_dataset_snapshots_product_id FOREIGN KEY (product_id) REFERENCES product_catalog(id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE model_versions (
  id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin PRIMARY KEY,
  product_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  version_code VARCHAR(64) NOT NULL,
  granularity VARCHAR(20) NOT NULL CHECK(granularity IN ('monthly','daily','shift')),
  prediction_horizon VARCHAR(48) NOT NULL,
  model_family VARCHAR(50) NOT NULL,
  artifact_uri VARCHAR(255) NOT NULL,
  artifact_sha256 char(64) NOT NULL,
  feature_schema_version VARCHAR(64) NOT NULL,
  dataset_snapshot_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  hyperparameters JSON NOT NULL DEFAULT (JSON_OBJECT()),
  evaluation_metrics JSON NOT NULL DEFAULT (JSON_OBJECT()),
  status VARCHAR(32) NOT NULL DEFAULT 'trained' CHECK(status IN ('trained','evaluated','candidate','approved','active','archived','rejected')),
  trained_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  approved_by CHAR(36) CHARACTER SET ascii COLLATE ascii_bin,
  activated_at DATETIME(6),
  supersedes_model_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin,
  UNIQUE(product_id,granularity,prediction_horizon,version_code),
  active_scope_key VARCHAR(124) CHARACTER SET ascii COLLATE ascii_bin GENERATED ALWAYS AS (CASE WHEN status = 'active' THEN CONCAT(product_id,'#',granularity,'#',prediction_horizon) ELSE NULL END) STORED,
  CONSTRAINT fk_model_versions_product_id FOREIGN KEY (product_id) REFERENCES product_catalog(id),
  CONSTRAINT fk_model_versions_dataset_snapshot_id FOREIGN KEY (dataset_snapshot_id) REFERENCES dataset_snapshots(id),
  CONSTRAINT fk_model_versions_approved_by FOREIGN KEY (approved_by) REFERENCES users(id),
  CONSTRAINT fk_model_versions_supersedes_model_id FOREIGN KEY (supersedes_model_id) REFERENCES model_versions(id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE training_runs (
  id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin PRIMARY KEY,
  model_version_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin,
  dataset_snapshot_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  code_commit VARCHAR(90),
  random_seed INT,
  train_from date,
  train_to date,
  validate_from date,
  validate_to date,
  test_from date,
  test_to date,
  metrics JSON NOT NULL DEFAULT (JSON_OBJECT()),
  status VARCHAR(32) NOT NULL CHECK(status IN ('queued','running','completed','failed','rejected')),
  started_at DATETIME(6),
  finished_at DATETIME(6),
  failure_message TEXT,
  CONSTRAINT fk_training_runs_model_version_id FOREIGN KEY (model_version_id) REFERENCES model_versions(id),
  CONSTRAINT fk_training_runs_dataset_snapshot_id FOREIGN KEY (dataset_snapshot_id) REFERENCES dataset_snapshots(id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE forecast_runs (
  id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin PRIMARY KEY,
  facility_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  parent_run_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin,
  event_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin,
  target_plan_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin,
  model_version_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin,
  engine_type VARCHAR(32) NOT NULL DEFAULT 'unavailable' CHECK(engine_type IN ('ml_model','statistical_baseline','engineering_baseline','scenario_estimate','unavailable')),
  as_of DATETIME(6) NOT NULL,
  horizon VARCHAR(48) NOT NULL,
  run_reason VARCHAR(40) NOT NULL,
  input_snapshot_hash char(64),
  status VARCHAR(32) NOT NULL DEFAULT 'queued' CHECK(status IN ('queued','running','completed','failed','unavailable','superseded')),
  quality_status VARCHAR(40) NOT NULL DEFAULT 'unknown',
  created_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  finished_at DATETIME(6),
  CONSTRAINT fk_forecast_runs_facility_id FOREIGN KEY (facility_id) REFERENCES facilities(id),
  CONSTRAINT fk_forecast_runs_parent_run_id FOREIGN KEY (parent_run_id) REFERENCES forecast_runs(id),
  CONSTRAINT fk_forecast_runs_event_id FOREIGN KEY (event_id) REFERENCES operational_events(id),
  CONSTRAINT fk_forecast_runs_target_plan_id FOREIGN KEY (target_plan_id) REFERENCES production_target_plans(id),
  CONSTRAINT fk_forecast_runs_model_version_id FOREIGN KEY (model_version_id) REFERENCES model_versions(id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE forecast_scenarios (
  id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin PRIMARY KEY,
  forecast_run_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  scenario_code VARCHAR(64) NOT NULL,
  eta_assumption DATETIME(6),
  assumptions JSON NOT NULL DEFAULT (JSON_OBJECT()),
  is_synthetic BOOLEAN NOT NULL DEFAULT 0,
  UNIQUE(forecast_run_id,scenario_code),
  CONSTRAINT fk_forecast_scenarios_forecast_run_id FOREIGN KEY (forecast_run_id) REFERENCES forecast_runs(id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE forecast_points (
  id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin PRIMARY KEY,
  forecast_run_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  scenario_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin,
  product_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  forecast_date date NOT NULL,
  forecast_t DECIMAL(20,3),
  lower_t DECIMAL(20,3),
  upper_t DECIMAL(20,3),
  source_status VARCHAR(40) NOT NULL DEFAULT 'model',
  scenario_scope_key VARCHAR(36) CHARACTER SET ascii COLLATE ascii_bin GENERATED ALWAYS AS (COALESCE(scenario_id,'GLOBAL')) STORED,
  UNIQUE KEY uq_forecast_point_scope (forecast_run_id,scenario_scope_key,product_id,forecast_date),
  CHECK(forecast_t IS NULL OR forecast_t>=0),
  CONSTRAINT fk_forecast_points_forecast_run_id FOREIGN KEY (forecast_run_id) REFERENCES forecast_runs(id),
  CONSTRAINT fk_forecast_points_scenario_id FOREIGN KEY (scenario_id) REFERENCES forecast_scenarios(id),
  CONSTRAINT fk_forecast_points_product_id FOREIGN KEY (product_id) REFERENCES product_catalog(id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE forecast_actual_evaluations (
  id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin PRIMARY KEY,
  forecast_point_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  approved_actual_record_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin,
  actual_t DECIMAL(20,3) NOT NULL CHECK(actual_t>=0),
  absolute_error_t DECIMAL(20,3),
  evaluated_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  evaluation_version int NOT NULL DEFAULT 1,
  UNIQUE(forecast_point_id,evaluation_version),
  CONSTRAINT fk_forecast_actual_evaluations_forecast_point_id FOREIGN KEY (forecast_point_id) REFERENCES forecast_points(id),
  CONSTRAINT fk_forecast_actual_evaluations_approved_actual_record_id FOREIGN KEY (approved_actual_record_id) REFERENCES production_records(id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE event_forecast_impacts (
  id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin PRIMARY KEY,
  event_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  before_run_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  after_run_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  product_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  comparison_status TEXT NOT NULL,
  delta_t DECIMAL(20,3),
  notes TEXT,
  created_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  CONSTRAINT fk_event_forecast_impacts_event_id FOREIGN KEY (event_id) REFERENCES operational_events(id),
  CONSTRAINT fk_event_forecast_impacts_before_run_id FOREIGN KEY (before_run_id) REFERENCES forecast_runs(id),
  CONSTRAINT fk_event_forecast_impacts_after_run_id FOREIGN KEY (after_run_id) REFERENCES forecast_runs(id),
  CONSTRAINT fk_event_forecast_impacts_product_id FOREIGN KEY (product_id) REFERENCES product_catalog(id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE model_monitoring_metrics (
  id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin PRIMARY KEY,
  model_version_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  period_start date NOT NULL,
  period_end date NOT NULL,
  sample_count int NOT NULL CHECK(sample_count>=0),
  mae DECIMAL(20,6),
  rmse DECIMAL(20,6),
  wape DECIMAL(20,6),
  regime VARCHAR(32) NOT NULL DEFAULT 'all',
  drift_metrics JSON NOT NULL DEFAULT (JSON_OBJECT()),
  calculated_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  CONSTRAINT fk_model_monitoring_metrics_model_version_id FOREIGN KEY (model_version_id) REFERENCES model_versions(id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE alerts (
  id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin PRIMARY KEY,
  facility_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin,
  unit_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin,
  event_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin,
  forecast_run_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin,
  severity VARCHAR(20) NOT NULL CHECK(severity IN ('info','warning','critical')),
  code VARCHAR(64) NOT NULL,
  message_ar TEXT NOT NULL,
  status VARCHAR(32) NOT NULL DEFAULT 'open'
 CHECK(status IN ('open','acknowledged','resolved','dismissed')),
  created_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  acknowledged_by CHAR(36) CHARACTER SET ascii COLLATE ascii_bin,
  acknowledged_at DATETIME(6),
  CONSTRAINT fk_alerts_facility_id FOREIGN KEY (facility_id) REFERENCES facilities(id),
  CONSTRAINT fk_alerts_unit_id FOREIGN KEY (unit_id) REFERENCES refinery_units(id),
  CONSTRAINT fk_alerts_event_id FOREIGN KEY (event_id) REFERENCES operational_events(id),
  CONSTRAINT fk_alerts_forecast_run_id FOREIGN KEY (forecast_run_id) REFERENCES forecast_runs(id),
  CONSTRAINT fk_alerts_acknowledged_by FOREIGN KEY (acknowledged_by) REFERENCES users(id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE async_jobs (
  id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin PRIMARY KEY,
  job_kind VARCHAR(64) NOT NULL,
  idempotency_key VARCHAR(128) NOT NULL UNIQUE,
  resource_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin,
  status VARCHAR(32) NOT NULL CHECK(status IN ('queued','running','completed','failed','cancelled')),
  attempts int NOT NULL DEFAULT 0,
  last_error TEXT,
  created_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  completed_at DATETIME(6)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE outbox_events (
  id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin PRIMARY KEY,
  event_type VARCHAR(64) NOT NULL,
  aggregate_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  payload JSON NOT NULL,
  occurred_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  processed_at DATETIME(6),
  attempts int NOT NULL DEFAULT 0
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE INDEX audit_logs_resource_idx ON audit_logs(resource_type,resource_id,happened_at);
CREATE INDEX planned_shutdown_unit_time_idx ON planned_shutdowns(unit_id,planned_start,planned_end);
CREATE INDEX crude_feed_date_idx ON crude_feed_records(unit_id,business_date,status);
CREATE INDEX production_records_date_idx ON production_records(product_id,unit_id,business_date,status);
CREATE UNIQUE INDEX monthly_observation_unique_src_idx ON monthly_observations(source_file_id,import_row_scope_key,metric_code,actual_or_target,period_month);
CREATE INDEX unit_status_time_idx ON unit_status_intervals(unit_id,starts_at,ends_at);
CREATE INDEX operational_events_unit_time_idx ON operational_events(unit_id,started_at,status);
CREATE INDEX downtime_intervals_unit_time_idx ON downtime_intervals(unit_id,started_at,actual_end_at);
CREATE UNIQUE INDEX uq_one_active_model_per_scope ON model_versions(active_scope_key);
CREATE INDEX forecast_runs_asof_idx ON forecast_runs(facility_id,as_of,status);
CREATE INDEX outbox_unprocessed_idx ON outbox_events(processed_at,occurred_at);

INSERT IGNORE INTO measurement_units(code,dimension,display_symbol) VALUES ('t','mass','t'),('kg','mass','kg'),('L','volume','L'),('kWh','energy','kWh'),('GJ','energy','GJ'),('h','time','h'),('pct','ratio','%');

-- IMPORTANT: InnoDB UNIQUE allows multiple NULL values. Generated scope columns above preserve
-- NULL-equivalent uniqueness behavior for critical keys; app must also validate business scopes.
-- A nullable active_product_id allows unlimited nonactive models, one active model per product.
-- MySQL permits composite FK constraints; Laravel migrations should implement and test every FK explicitly.
-- Review production data lineage, product stages, monthly import approvals and event overlap invariants before deployment.
